/*
 * Alien Invasion Probability Calculator
 *
 * This program calculates the probability of an alien invasion based on the
 * given parameters.
 */

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Define a struct to hold the input parameters
typedef struct {
    int population;
    int alien_count;
    int invasion_duration;
    int defensive_systems;
} AlienInvasionParams;

// Define a struct to hold the output parameters
typedef struct {
    double invasion_probability;
    double destruction_probability;
} AlienInvasionResults;

// Function to calculate the invasion probability
AlienInvasionResults calculate_invasion_probability(AlienInvasionParams params) {
    // Calculate the invasion probability
    double invasion_probability = params.alien_count / (double)params.population;

    // Calculate the destruction probability
    double destruction_probability = pow(invasion_probability, params.invasion_duration);

    // Return the results
    AlienInvasionResults results;
    results.invasion_probability = invasion_probability;
    results.destruction_probability = destruction_probability;
    return results;
}

// Main function
int main() {
    // Initialize the input parameters
    AlienInvasionParams params;
    params.population = 1000000;
    params.alien_count = 1000;
    params.invasion_duration = 10;
    params.defensive_systems = 5;

    // Calculate the invasion probability
    AlienInvasionResults results = calculate_invasion_probability(params);

    // Print the results
    printf("Invasion probability: %.2f%%\n", results.invasion_probability * 100);
    printf("Destruction probability: %.2f%%\n", results.destruction_probability * 100);

    return 0;
}

