//Falcon-180B DATASET v1.0 Category: Greedy Algorithms ; Style: innovative
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

// Function to find the maximum value in an array
int findMax(int arr[], int n)
{
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to implement the greedy algorithm
void greedyAlgorithm(int arr[], int n, int k)
{
    int max = findMax(arr, n);
    int sum = 0;
    int count = 0;

    // Iterate through the array and add elements to the sum until the sum exceeds the given value
    for (int i = 0; i < n; i++) {
        if (arr[i] == max) {
            sum += arr[i];
            count++;
        }
        if (sum >= k) {
            break;
        }
    }

    // Print the result
    printf("Maximum sum of %d can be obtained by selecting %d elements:\n", k, count);
    for (int i = 0; i < count; i++) {
        printf("%d ", max);
    }
    printf("\n");
}

// Main function to test the greedy algorithm
int main()
{
    int arr1[] = {1, 2, 3, 4, 5};
    int n1 = sizeof(arr1)/sizeof(arr1[0]);
    int k1 = 7;
    printf("Example 1:\n");
    greedyAlgorithm(arr1, n1, k1);

    int arr2[] = {5, 2, 1, 3, 4};
    int n2 = sizeof(arr2)/sizeof(arr2[0]);
    int k2 = 10;
    printf("\nExample 2:\n");
    greedyAlgorithm(arr2, n2, k2);

    return 0;
}

//Falcon-180B DATASET v1.0 Category: Movie Rating System ; Style: calm
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NAME_LENGTH 100
#define MAX_RATINGS 5

// Movie structure
typedef struct {
    char name[MAX_NAME_LENGTH];
    int ratings[MAX_RATINGS];
    int numRatings;
} Movie;

// Function prototypes
void addMovie(Movie *movies, int numMovies, char *name);
void printMovie(Movie movie);
void rateMovie(Movie *movies, int numMovies, char *name, int rating);
double averageRating(Movie movie);

int main() {
    int numMovies = 0;
    Movie movies[10];

    // Add some movies
    addMovie(movies, numMovies, "The Shawshank Redemption");
    addMovie(movies, numMovies, "The Godfather");
    addMovie(movies, numMovies, "The Dark Knight");

    // Print all movies with their average ratings
    for (int i = 0; i < numMovies; i++) {
        printf("Movie: %s\n", movies[i].name);
        printf("Average rating: %.2f\n\n", averageRating(movies[i]));
    }

    return 0;
}

void addMovie(Movie *movies, int numMovies, char *name) {
    strcpy(movies[numMovies].name, name);
    movies[numMovies].numRatings = 0;
    for (int i = 0; i < MAX_RATINGS; i++) {
        movies[numMovies].ratings[i] = 0;
    }
    numMovies++;
}

void printMovie(Movie movie) {
    printf("Movie: %s\n", movie.name);
}

void rateMovie(Movie *movies, int numMovies, char *name, int rating) {
    int index = -1;
    for (int i = 0; i < numMovies; i++) {
        if (strcmp(movies[i].name, name) == 0) {
            index = i;
            break;
        }
    }

    if (index!= -1) {
        movies[index].ratings[movies[index].numRatings] = rating;
        movies[index].numRatings++;
    }
}

double averageRating(Movie movie) {
    int sum = 0;
    for (int i = 0; i < movie.numRatings; i++) {
        sum += movie.ratings[i];
    }
    return (double) sum / movie.numRatings;
}

