void analyzeText(char* text, WordFrequency words[]) {
    char* token = strtok(text, ",.?!;:");
    while (token!= NULL) {
        int wordIndex = -1;
        for (int i = 0; i < MAX_WORDS; i++) {
            if (strcmp(token, words[i].word) == 0) {
