    int i, j;
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            graph[i][j] = 0;
        }
    }
}

void add_edge(int u, int v) {
    graph[u][v] = 1;
    graph[v][u] = 1;
}

int is_connected(int u, int c) {
    int i;
    colors[u] = c;
    for (i = 0; i < n; i++) {
        if (graph[u][i] == 1 && colors[i] == 0) {
            if (!is_connected(i, c + 1)) {
                return 0;
            }
        }
    }
    return 1;
}

