#include <stdio.h>
#include <stdlib.h>

// A job has a start time, end time, and profit.
typedef struct Job {
  int start;
  int end;
  int profit;
} Job;

// Compares two jobs by their end times.
int compareJobs(const void *a, const void *b) {
  const Job *job1 = (const Job *)a;
  const Job *job2 = (const Job *)b;
  return job1->end - job2->end;
}

// The main function that returns the maximum profit from a set of jobs.
int maxProfit(Job jobs[], int n) {
  // Sort the jobs by their end times.
  qsort(jobs, n, sizeof(Job), compareJobs);

  // Initialize the maximum profit to 0.
  int max_profit = 0;

  // Initialize the current time to 0.
  int current_time = 0;

  // Iterate over the jobs.
  for (int i = 0; i < n; i++) {
    // If the current time is less than the start time of the current job,
    // then wait until the current job can be started.
    if (current_time < jobs[i].start) {
      current_time = jobs[i].start;
    }

    // If the current time is less than the end time of the current job,
    // then add the profit of the current job to the maximum profit.
    if (current_time < jobs[i].end) {
      max_profit += jobs[i].profit;
    }

    // Update the current time to the end time of the current job.
    current_time = jobs[i].end;
  }

  // Return the maximum profit.
  return max_profit;
}

// A utility function to print a Job
void printJob(Job job) {
  printf("Start: %d, End: %d, Profit: %d\n", job.start, job.end, job.profit);
}

// A utility function to create a Job
Job createJob(int start, int end, int profit) {
  Job job;
  job.start = start;
  job.end = end;
  job.profit = profit;
  return job;
}

// Driver code to test the above functions
int main() {
  // Create a set of jobs.
  Job jobs[] = {createJob(1, 2, 50), createJob(3, 5, 20), createJob(6, 19, 100),
                createJob(2, 10, 20), createJob(1, 9, 30), createJob(10, 15, 50)};
  int n = sizeof(jobs) / sizeof(jobs[0]);

  // Print the jobs.
  printf("Jobs:\n");
  for (int i = 0; i < n; i++) {
    printJob(jobs[i]);
  }

  // Find the maximum profit from the set of jobs.
  int max_profit = maxProfit(jobs, n);

  // Print the maximum profit.
  printf("Maximum profit: %d\n", max_profit);

  return 0;
}

