                    printf("O");
                } else if (map[i][j] == 3) {
                    printf("X");
                } else {
                    printf(" ");
                }
            }
            printf("\n");
        }

        // Move the pacman
        switch (direction) {
            case 0:
                pacman_y--;
                break;
            case 1:
                pacman_x++;
                break;
            case 2:
                pacman_y++;
                break;
            case 3:
                pacman_x--;
                break;
        }

        // Check if the pacman has eaten the food
        if (pacman_x == food_x && pacman_y == food_y) {
            score++;
            food_x = rand() % SCREEN_WIDTH;
            food_y = rand() % SCREEN_HEIGHT;
        }

        // Check if the pacman has hit a wall
        if (pacman_x < 0 || pacman_x >= SCREEN_WIDTH || pacman_y < 0 || pacman_y >= SCREEN_HEIGHT) {
            // Game over
            break;
        }

        // Update the map
        map[pacman_y][pacman_x] = 3;

        // Sleep for a while
        t = time(NULL);
        while (time(NULL) - t < 0.05) {}
    }

