#include <stdio.h>
#include <stdlib.h>

#define MAX_PROCESSES 5
#define MAX_INSTRUCTIONS 10

typedef struct Process {
    int process_id;
    int arrival_time;
    int burst_time;
    int waiting_time;
    int turn_around_time;
} Process;

Process processes[MAX_PROCESSES];

void calculate_waiting_time(int i) {
    processes[i].waiting_time = 0;
    for (int j = 0; j < i; j++) {
        processes[i].waiting_time += processes[j].burst_time;
    }
}

void calculate_turn_around_time(int i) {
    processes[i].turn_around_time = processes[i].burst_time + processes[i].waiting_time;
}

void simulate_cpu_scheduling() {
    int current_time = 0;
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (processes[i].arrival_time <= current_time && processes[i].burst_time > 0) {
            processes[i].burst_time--;
            current_time++;
        }
    }
}

int main() {
    // Initialize processes
    for (int i = 0; i < MAX_PROCESSES; i++) {
        processes[i].process_id = i + 1;
        processes[i].arrival_time = rand() % MAX_INSTRUCTIONS;
        processes[i].burst_time = rand() % MAX_INSTRUCTIONS;
    }

    // Calculate waiting time and turn-around time
    for (int i = 0; i < MAX_PROCESSES; i++) {
        calculate_waiting_time(i);
        calculate_turn_around_time(i);
    }

    // Simulate CPU scheduling
    simulate_cpu_scheduling();

    // Print results
    for (int i = 0; i < MAX_PROCESSES; i++) {
        printf("Process ID: %d, Waiting Time: %d, Turn-around Time: %d\n", processes[i].process_id, processes[i].waiting_time, processes[i].turn_around_time);
    }

    return 0;
}

