typedef struct {
    char *data;
    int len;
} buffer_t;

void compress(buffer_t *buffer) {
    int i, j, k, len = 0;
    char *data = buffer->data;

    // Step 1: Remove duplicates
    for (i = 0; i < buffer->len; i++) {
        char curr = data[i];
        for (j = i + 1; j < buffer->len; j++) {
            if (curr == data[j]) {
                data[len] = curr;
                len++;
                i = j;
                break;
            }
        }
    }

    // Step 2: Run-length encode
    for (i = 0; i < buffer->len; i++) {
        char curr = data[i];
        if (curr == '\0') {
            continue;
        }
        for (j = i + 1; j < buffer->len; j++) {
            if (data[j] == curr) {
                data[len] = curr;
                len++;
                i = j;
                break;
            }
        }
    }

    // Step 3: Huffman encode
    for (i = 0; i < buffer->len; i++) {
        char curr = data[i];
        if (curr == '\0') {
            continue;
        }
        for (j = i + 1; j < buffer->len; j++) {
            if (data[j] == curr) {
                data[len] = curr;
                len++;
                i = j;
                break;
            }
        }
    }

    buffer->len = len;
