#include <stdbool.h>
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MIN_PASSWORD_LENGTH 8
#define PASSWORD_SIZE 256

bool check_password_strength(const char *password) {
    bool has_lower = false;
    bool has_upper = false;
    bool has_digit = false;
    bool has_special = false;

    int password_length = strlen(password);

    if (password_length < MIN_PASSWORD_LENGTH) {
        return false;
    }

    for (int i = 0; password[i]; i++) {
        if (isdigit(password[i])) {
            has_digit = true;
        }
        if (isalpha(password[i])) {
            if (islower(password[i])) {
                has_lower = true;
            } else {
                has_upper = true;
            }
        }
        if (strchr("!@#$%^&*()-+={}[]|\\:;\"'<>,.?/~`", password[i])) {
            has_special = true;
        }

        if (has_lower && has_upper && has_digit && has_special) {
            break;
        }
    }

    return has_lower && has_upper && has_digit && has_special;
}

void print_password_strength(const char *password) {
    bool strong_password = check_password_strength(password);

    printf("Password \"%s\"", password);

    if (strong_password) {
        printf(" is strong.\n");
    } else {
        printf(" is weak.\n");
        printf("Consider adding lowercase letters, uppercase letters, digits, and special characters to improve its strength.\n");
    }
}

int main() {
    const char *passwords[] = {"password123", "Password123!", "MyPassword$", "letmein", "12345678"};

    for (int i = 0; i < sizeof(passwords) / sizeof(char *); i++) {
        print_password_strength(passwords[i]);
    }

    return 0;
}

