#define MAX_ROOMS 10

typedef struct {
    int room_number;
    char status;
    float price_per_night;
} Room;

void initialize_rooms(Room rooms[MAX_ROOMS]);
void print_room_status(Room room);
void book_room(Room *room, int guest_count, float discount);

int main() {
    Room rooms[MAX_ROOMS];
    int choice;

    initialize_rooms(rooms);

    while (1) {
        printf("\n------------------------\n");
        printf("| Hotel Management System |\n");
        printf("------------------------|\n");
        printf("| 1. View Rooms           |\n");
        printf("| 2. Book Room           |\n");
        printf("| 3. Exit                |\n");
        printf("------------------------|\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                for (int i = 0; i < MAX_ROOMS; i++) {
                    print_room_status(rooms[i]);
                }
                break;
            case 2: {
                int room_number;
                printf("Enter room number: ");
                scanf("%d", &room_number);

                for (int i = 0; i < MAX_ROOMS; i++) {
                    if (rooms[i].room_number == room_number) {
                        int guest_count;
                        float discount;
                        printf("Enter number of guests: ");
                        scanf("%d", &guest_count);
                        printf("Enter discount percentage: ");
                        scanf("%f", &discount);
                        book_room(&rooms[i], guest_count, discount);
                        break;
                    }
                }
                break;
            }
            case 3:
                exit(0);
            default:
                printf("Invalid choice!\n");
        }
    }

    return 0;
